+const { toInternational } = require('./dialing');
+
+function normalize(raw) {
+  const compact = raw.trim().replace(' ', '');
+  const international = toInternational(compact);
+  return international.replace(/[().-]/g, '');
+}
+
+module.exports = { normalize };
